import{_t as e,it as t,n,rt as r}from"./chunks/framework.BvGh1SPQ.js";var i=JSON.parse(`{"title":"micro509/der","description":"","frontmatter":{"title":"micro509/der","packageVersion":"0.13.0"},"headers":[],"relativePath":"api/der.md","filePath":"site/versions/v0.13.0/api/der.md","lastUpdated":0}`),a={name:`api/der.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="micro509-der" tabindex="-1"><code>micro509/der</code> <a class="header-anchor" href="#micro509-der" aria-label="Permalink to “micro509/der”">​</a></h1><p>DER reading and writing primitives.</p><p>The building blocks every other entrypoint is made of, for the cases the typed APIs do not cover:</p><ul><li>decoding a private extension&#39;s <a href="https://www.rfc-editor.org/info/rfc5280/#section-4.1" target="_blank" rel="noreferrer"><code>extnValue</code></a> inside an <a href="https://micro509.kjanat.dev/next/api/x509#type-extensiondecoder" target="_blank" rel="noreferrer"><code>ExtensionDecoder</code></a></li><li>encoding the bytes a <a href="https://micro509.kjanat.dev/next/api/x509#type-customextension" target="_blank" rel="noreferrer"><code>CustomExtension</code></a> carries</li><li>inspecting a structure this library does not model</li></ul><p>Reading accepts definite lengths and minimal length encodings, rejects the high-tag-number form, and applies a nesting-depth guard capped at <a href="/v0.13.0/api/var/DEFAULT_MAX_DER_DEPTH"><code>DEFAULT_MAX_DER_DEPTH</code></a>. BER-only constructs fail.</p><p>Readers and decoders take untrusted bytes, so each one comes as a pair:</p><ul><li><a href="https://micro509.kjanat.dev/next/api/der#fn-decodederinteger" target="_blank" rel="noreferrer"><code>decodeDerInteger</code></a> returns a <a href="https://micro509.kjanat.dev/next/api/der#type-decodederresult" target="_blank" rel="noreferrer"><code>DecodeDerResult</code></a></li><li><a href="https://micro509.kjanat.dev/next/api/der#fn-decodederintegerorthrow" target="_blank" rel="noreferrer"><code>decodeDerIntegerOrThrow</code></a> throws</li></ul><p>Writers take typed input and throw, matching <a href="https://micro509.kjanat.dev/next/api/x509#fn-encodename" target="_blank" rel="noreferrer"><code>encodeName</code></a> and <a href="https://micro509.kjanat.dev/next/api/pem#fn-pemencode" target="_blank" rel="noreferrer"><code>pemEncode</code></a>.</p><p>All operations are synchronous.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><span id="fn-decodederbitstring"></span><a href="/v0.13.0/api/fn/decodeDerBitString"><code>decodeDerBitString</code></a> — Decodes a BIT STRING element (tag <code>0x03</code>) into a <a href="/v0.13.0/api/type/DerBitString"><code>DerBitString</code></a>.</li><li><span id="fn-decodederbitstringorthrow"></span><a href="/v0.13.0/api/fn/decodeDerBitStringOrThrow"><code>decodeDerBitStringOrThrow</code></a> — Decodes a BIT STRING element (tag <code>0x03</code>) into a <a href="/v0.13.0/api/type/DerBitString"><code>DerBitString</code></a>.</li><li><span id="fn-decodederboolean"></span><a href="/v0.13.0/api/fn/decodeDerBoolean"><code>decodeDerBoolean</code></a> — Decodes a BOOLEAN element (tag <code>0x01</code>).</li><li><span id="fn-decodederbooleanorthrow"></span><a href="/v0.13.0/api/fn/decodeDerBooleanOrThrow"><code>decodeDerBooleanOrThrow</code></a> — Decodes a BOOLEAN element (tag <code>0x01</code>).</li><li><span id="fn-decodederinteger"></span><a href="/v0.13.0/api/fn/decodeDerInteger"><code>decodeDerInteger</code></a> — Decodes an INTEGER element (tag <code>0x02</code>) into a <code>number</code>.</li><li><span id="fn-decodederintegerorthrow"></span><a href="/v0.13.0/api/fn/decodeDerIntegerOrThrow"><code>decodeDerIntegerOrThrow</code></a> — Decodes an INTEGER element (tag <code>0x02</code>) into a <code>number</code>.</li><li><span id="fn-decodederoctetstring"></span><a href="/v0.13.0/api/fn/decodeDerOctetString"><code>decodeDerOctetString</code></a> — Decodes an OCTET STRING element (tag <code>0x04</code>) into its payload bytes.</li><li><span id="fn-decodederoctetstringorthrow"></span><a href="/v0.13.0/api/fn/decodeDerOctetStringOrThrow"><code>decodeDerOctetStringOrThrow</code></a> — Decodes an OCTET STRING element (tag <code>0x04</code>) into its payload bytes.</li><li><span id="fn-decodederoid"></span><a href="/v0.13.0/api/fn/decodeDerOid"><code>decodeDerOid</code></a> — Decodes an OBJECT IDENTIFIER element (tag <code>0x06</code>) into dotted-decimal form.</li><li><span id="fn-decodederoidorthrow"></span><a href="/v0.13.0/api/fn/decodeDerOidOrThrow"><code>decodeDerOidOrThrow</code></a> — Decodes an OBJECT IDENTIFIER element (tag <code>0x06</code>) into dotted-decimal form.</li><li><span id="fn-decodederstring"></span><a href="/v0.13.0/api/fn/decodeDerString"><code>decodeDerString</code></a> — Decodes a string element into text, dispatching on its tag.</li><li><span id="fn-decodederstringorthrow"></span><a href="/v0.13.0/api/fn/decodeDerStringOrThrow"><code>decodeDerStringOrThrow</code></a> — Decodes a string element into text, dispatching on its tag.</li><li><span id="fn-decodedertime"></span><a href="/v0.13.0/api/fn/decodeDerTime"><code>decodeDerTime</code></a> — Decodes a UTCTime (tag <code>0x17</code>) or GeneralizedTime (tag <code>0x18</code>) element into a <code>Date</code>.</li><li><span id="fn-decodedertimeorthrow"></span><a href="/v0.13.0/api/fn/decodeDerTimeOrThrow"><code>decodeDerTimeOrThrow</code></a> — Decodes a UTCTime (tag <code>0x17</code>) or GeneralizedTime (tag <code>0x18</code>) element into a <code>Date</code>.</li><li><span id="fn-derchildren"></span><a href="/v0.13.0/api/fn/derChildren"><code>derChildren</code></a> — Reads the direct children of a constructed <code>parent</code> within <code>source</code>.</li><li><span id="fn-derchildrenorthrow"></span><a href="/v0.13.0/api/fn/derChildrenOrThrow"><code>derChildrenOrThrow</code></a> — Reads the direct children of a constructed <code>parent</code> within <code>source</code>.</li><li><span id="fn-readderelement"></span><a href="/v0.13.0/api/fn/readDerElement"><code>readDerElement</code></a> — Reads one TLV element from <code>bytes</code> starting at <code>offset</code>.</li><li><span id="fn-readderelementorthrow"></span><a href="/v0.13.0/api/fn/readDerElementOrThrow"><code>readDerElementOrThrow</code></a> — Reads one TLV element from <code>bytes</code> starting at <code>offset</code>.</li><li><span id="fn-readderroot"></span><a href="/v0.13.0/api/fn/readDerRoot"><code>readDerRoot</code></a> — Reads the single top-level TLV element from <code>bytes</code>.</li><li><span id="fn-readderrootorthrow"></span><a href="/v0.13.0/api/fn/readDerRootOrThrow"><code>readDerRootOrThrow</code></a> — Reads the single top-level TLV element from <code>bytes</code>.</li><li><span id="fn-readdersequence"></span><a href="/v0.13.0/api/fn/readDerSequence"><code>readDerSequence</code></a> — Reads a DER-encoded SEQUENCE from <code>bytes</code> and returns its direct children.</li><li><span id="fn-readdersequenceorthrow"></span><a href="/v0.13.0/api/fn/readDerSequenceOrThrow"><code>readDerSequenceOrThrow</code></a> — Reads a DER-encoded SEQUENCE from <code>bytes</code> and returns its direct children.</li><li><span id="fn-hextobytes"></span><a href="/v0.13.0/api/fn/hexToBytes"><code>hexToBytes</code></a> — Converts a hex string (even or odd length) to a <code>Uint8Array</code>.</li><li><span id="fn-tohex"></span><a href="/v0.13.0/api/fn/toHex"><code>toHex</code></a> — Converts raw bytes to a lowercase hex string with no separator.</li><li><span id="fn-assertdermaxdepth"></span><a href="/v0.13.0/api/fn/assertDerMaxDepth"><code>assertDerMaxDepth</code></a> — Walks the full DER tree rooted in <code>bytes</code>.</li><li><span id="fn-derbitstring"></span><a href="/v0.13.0/api/fn/derBitString"><code>derBitString</code></a> — Encodes a DER BIT STRING (tag <code>0x03</code>).</li><li><span id="fn-derbmpstring"></span><a href="/v0.13.0/api/fn/derBmpString"><code>derBmpString</code></a> — Encodes a DER BMPString (tag <code>0x1e</code>) as big-endian UTF-16.</li><li><span id="fn-derboolean"></span><a href="/v0.13.0/api/fn/derBoolean"><code>derBoolean</code></a> — Encodes a DER BOOLEAN (tag <code>0x01</code>): <code>true</code> → <code>0xff</code>, <code>false</code> → <code>0x00</code>.</li><li><span id="fn-concatbytes"></span><a href="/v0.13.0/api/fn/concatBytes"><code>concatBytes</code></a> — Concatenates multiple byte arrays into a single <code>Uint8Array</code>.</li><li><span id="fn-derexplicitcontext"></span><a href="/v0.13.0/api/fn/derExplicitContext"><code>derExplicitContext</code></a> — Wraps a value in an explicit context-specific constructed tag (<code>0xa0 + tag</code>).</li><li><span id="fn-dergeneralizedtime"></span><a href="/v0.13.0/api/fn/derGeneralizedTime"><code>derGeneralizedTime</code></a> — Encodes a <code>Date</code> as a DER GeneralizedTime (tag <code>0x18</code>), format <code>YYYYMMDDHHMMSSZ</code>.</li><li><span id="fn-deria5string"></span><a href="/v0.13.0/api/fn/derIa5String"><code>derIa5String</code></a> — Encodes a DER IA5String (tag <code>0x16</code>).</li><li><span id="fn-derimplicitconstructedcontext"></span><a href="/v0.13.0/api/fn/derImplicitConstructedContext"><code>derImplicitConstructedContext</code></a> — Wraps a value in an implicit context-specific constructed tag (<code>0xa0 + tag</code>).</li><li><span id="fn-derimplicitprimitivecontext"></span><a href="/v0.13.0/api/fn/derImplicitPrimitiveContext"><code>derImplicitPrimitiveContext</code></a> — Wraps a value in an implicit context-specific primitive tag (<code>0x80 + tag</code>).</li><li><span id="fn-derinteger"></span><a href="/v0.13.0/api/fn/derInteger"><code>derInteger</code></a> — Encodes raw big-endian bytes as a DER INTEGER (tag <code>0x02</code>).</li><li><span id="fn-derintegerfromnumber"></span><a href="/v0.13.0/api/fn/derIntegerFromNumber"><code>derIntegerFromNumber</code></a> — Encodes a non-negative JavaScript <code>number</code> as a DER INTEGER.</li><li><span id="fn-dernull"></span><a href="/v0.13.0/api/fn/derNull"><code>derNull</code></a> — Produces a DER NULL element (tag <code>0x05</code>, zero-length value).</li><li><span id="fn-deroid"></span><a href="/v0.13.0/api/fn/derOid"><code>derOid</code></a> — Encodes a dotted-decimal OID string as a DER OBJECT IDENTIFIER (tag <code>0x06</code>).</li><li><span id="fn-deroctetstring"></span><a href="/v0.13.0/api/fn/derOctetString"><code>derOctetString</code></a> — Wraps raw bytes in an OCTET STRING element (tag <code>0x04</code>).</li><li><span id="fn-derprintablestring"></span><a href="/v0.13.0/api/fn/derPrintableString"><code>derPrintableString</code></a> — Encodes a DER PrintableString (tag <code>0x13</code>).</li><li><span id="fn-dersequence"></span><a href="/v0.13.0/api/fn/derSequence"><code>derSequence</code></a> — Wraps concatenated children in a SEQUENCE (tag <code>0x30</code>).</li><li><span id="fn-derset"></span><a href="/v0.13.0/api/fn/derSet"><code>derSet</code></a> — Wraps children in a SET (tag <code>0x31</code>) after DER-sorting them lexicographically by encoded bytes,</li><li><span id="fn-dertime"></span><a href="/v0.13.0/api/fn/derTime"><code>derTime</code></a> — Encodes a <code>Date</code> as the appropriate DER time type per RFC 5280.</li><li><span id="fn-dertlv"></span><a href="/v0.13.0/api/fn/derTlv"><code>derTlv</code></a> — Builds a complete DER TLV (tag-length-value) element:</li><li><span id="fn-deruniversalstring"></span><a href="/v0.13.0/api/fn/derUniversalString"><code>derUniversalString</code></a> — Encodes a DER UniversalString (tag <code>0x1c</code>) as big-endian UTF-32.</li><li><span id="fn-derutctime"></span><a href="/v0.13.0/api/fn/derUtcTime"><code>derUtcTime</code></a> — Encodes a <code>Date</code> as a DER UTCTime (tag <code>0x17</code>), format <code>YYMMDDHHMMSSZ</code>.</li><li><span id="fn-derutf8string"></span><a href="/v0.13.0/api/fn/derUtf8String"><code>derUtf8String</code></a> — Encodes a DER UTF8String (tag <code>0x0c</code>).</li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h2><ul><li><span id="type-decodedererrorcode"></span><a href="/v0.13.0/api/type/DecodeDerErrorCode"><code>DecodeDerErrorCode</code></a> — Machine-readable failure reason for the DER readers and decoders.</li><li><span id="type-decodederfailure"></span><a href="/v0.13.0/api/type/DecodeDerFailure"><code>DecodeDerFailure</code></a> — Structured failure payload for DER reading and decoding.</li><li><span id="type-decodederresult"></span><a href="/v0.13.0/api/type/DecodeDerResult"><code>DecodeDerResult</code></a> — Success-or-failure result from a DER reader or decoder.</li><li><span id="type-derbitstring"></span><a href="/v0.13.0/api/type/DerBitString"><code>DerBitString</code></a> — A BIT STRING payload and the number of unused trailing bits in its final byte.</li><li><span id="type-derelement"></span><a href="/v0.13.0/api/type/DerElement"><code>DerElement</code></a> — A single parsed ASN.1 TLV element with byte-range metadata.</li><li><span id="type-readrootelementoptions"></span><a href="/v0.13.0/api/type/ReadRootElementOptions"><code>ReadRootElementOptions</code></a> — Options for <code>readRootElement</code>.</li><li><span id="type-readsequencechildrenoptions"></span><a href="/v0.13.0/api/type/ReadSequenceChildrenOptions"><code>ReadSequenceChildrenOptions</code></a> — Options for <code>readSequenceChildren</code>.</li></ul><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><ul><li><span id="var-default_max_der_depth"></span><a href="/v0.13.0/api/var/DEFAULT_MAX_DER_DEPTH"><code>DEFAULT_MAX_DER_DEPTH</code></a> — Maximum nesting depth allowed when recursively walking a DER structure.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};